{
  "application": "web-design",
  "case_id": "case-media-entertainment-corporate-snapframe",
  "language": "en",
  "site": {
    "type": "corporate",
    "page_count": 1,
    "audience": "general consumers, creators, parents, and businesses interested in a social media photo and video sharing platform",
    "tone": "modern, bold, playful",
    "responsive": true,
    "dark_mode": false
  },
  "brief": {
    "title": "SnapFrame — Capture, Create & Share What You Love",
    "one_liner": "SnapFrame is a social media platform that makes it easy to capture, create, and share what you love with the people who matter most.",
    "goal": "Serve as the corporate 'About' landing page that introduces the platform's mission, highlights key features, promotes safety tools, showcases creator opportunities, and surfaces the latest news articles."
  },
  "pages": [
    {
      "page_id": "home",
      "file": "index.html",
      "sections": [
        "hero",
        "features",
        "safety",
        "creators",
        "tagline-banner",
        "news",
        "cta-download",
        "footer"
      ],
      "objective": "Introduce the platform's value proposition, highlight features, safety, and creator tools, display recent news articles, and provide download links and comprehensive footer navigation."
    }
  ],
  "navigation": [
    {
      "from": "home",
      "trigger": "Log in button in header",
      "to": "home"
    },
    {
      "from": "home",
      "trigger": "Try it now button in hero",
      "to": "home"
    },
    {
      "from": "home",
      "trigger": "Features link in features section",
      "to": "home"
    },
    {
      "from": "home",
      "trigger": "Safety tools link in safety section",
      "to": "home"
    },
    {
      "from": "home",
      "trigger": "Creator link in creators section",
      "to": "home"
    },
    {
      "from": "home",
      "trigger": "View more link in news section",
      "to": "home"
    }
  ],
  "interactions": [
    {
      "id": "hamburger-menu",
      "page": "home",
      "trigger": "Click hamburger menu icon in header",
      "expected": "Mobile navigation menu opens revealing site links",
      "type": "toggle"
    },
    {
      "id": "news-carousel",
      "page": "home",
      "trigger": "Scroll or swipe through news article cards",
      "expected": "News article cards scroll horizontally to reveal additional articles",
      "type": "navigation"
    }
  ],
  "data_display": [
    {
      "id": "news-articles",
      "page": "home",
      "type": "list",
      "source_ref": "## News Articles",
      "expected_content": [
        "Close Friends Only Podcast",
        "February 18, 2026",
        "Sticker Ideas and Tips for Finding the Best Ones",
        "February 4, 2026",
        "Watch Reels on the Big Screen",
        "December 17, 2025"
      ],
      "description": "A horizontally scrollable list of recent news articles with thumbnail images, category tags, titles, and publication dates."
    },
    {
      "id": "footer-links",
      "page": "home",
      "type": "list",
      "source_ref": "## Footer Navigation",
      "expected_content": [
        "Our story",
        "Leadership",
        "Features",
        "Safety tools",
        "Community",
        "Privacy"
      ],
      "description": "Comprehensive footer navigation organized into columns: About (Our story, Leadership, Brand), Features (Reels, Stories, DMs, Search & Explore), Safety (Safety tools, Privacy tools, Account security), Community (School Partnerships, Teen Accounts, Anti-Bullying, Parents, Programs), and external links."
    }
  ]
}

