[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>SnapFrame — Capture, Create &amp; Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet" />
  <style>
    /* ===== RESET & BASE ===== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --black: #000000;
      --purple: #7638FA;
      --purple-light: #9B6FFB;
      --purple-pale: #F3EEFF;
      --orange: #FF7A00;
      --orange-light: #FF9A3C;
      --white: #FFFFFF;
      --gray-50: #F9F9FB;
      --gray-100: #F1F1F5;
      --gray-200: #E4E4EE;
      --gray-400: #A0A0B8;
      --gray-600: #555570;
      --gray-800: #1A1A2E;
      --font: 'Plus Jakarta Sans', system-ui, sans-serif;
      --radius-sm: 8px;
      --radius-md: 16px;
      --radius-lg: 24px;
      --radius-xl: 32px;
      --radius-pill: 999px;
      --shadow-card: 0 4px 24px rgba(0,0,0,0.08);
      --shadow-card-hover: 0 12px 40px rgba(118,56,250,0.18);
      --max-w: 1200px;
      --px: clamp(20px, 5vw, 80px);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      background: var(--white);
      color: var(--gray-800);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    img { display: block; max-width: 100%; }
    button { font-family: var(--font); cursor: pointer; border: none; }

    /* ===== UTILITY ===== */
    .container { max-width: var(--max-w); margin: 0 auto; padding: 0 var(--px); }
    .visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

    /* ===== HEADER ===== */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-200);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 68px;
      gap: 24px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      font-size: 1.25rem;
      color: var(--black);
      flex-shrink: 0;
    }

    .logo-icon {
      width: 36px;
      height: 36px;
      background: linear-gradient(135deg, var(--purple), var(--orange));
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg { width: 20px; height: 20px; fill: white; }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .btn-login {
      padding: 9px 22px;
      border-radius: var(--radius-pill);
      font-size: 0.9rem;
      font-weight: 600;
      border: 2px solid var(--black);
      background: transparent;
      color: var(--black);
      transition: background 0.18s, color 0.18s;
    }

    .btn-login:hover { background: var(--black); color: var(--white); }

    .hamburger {
      display: none;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      width: 44px;
      height: 44px;
      background: none;
      border: none;
      gap: 5px;
      cursor: pointer;
      border-radius: var(--radius-sm);
      transition: background 0.15s;
    }

    .hamburger:hover { background: var(--gray-100); }
    .hamburger span {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--black);
      border-radius: 2px;
      transition: transform 0.25s, opacity 0.25s;
      transform-origin: center;
    }

    .hamburger[aria-expanded="true"] span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger[aria-expanded="true"] span:nth-child(2) { opacity: 0; transform: scaleX(0); }
    .hamburger[aria-expanded="true"] span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    /* Mobile nav overlay */
    .mobile-nav {
      display: none;
      position: fixed;
      inset: 68px 0 0 0;
      background: var(--white);
      z-index: 99;
      padding: 32px var(--px);
      flex-direction: column;
      gap: 8px;
      overflow-y: auto;
    }

    .mobile-nav.open { display: flex; }

    .mobile-nav a {
      font-size: 1.25rem;
      font-weight: 600;
      padding: 14px 0;
      border-bottom: 1px solid var(--gray-100);
      color: var(--gray-800);
      transition: color 0.15s;
    }

    .mobile-nav a:hover { color: var(--purple); }

    .mobile-nav .mobile-nav-login {
      margin-top: 16px;
      display: inline-block;
      padding: 14px 28px;
      background: var(--purple);
      color: var(--white);
      border-radius: var(--radius-pill);
      font-size: 1rem;
      font-weight: 700;
      text-align: center;
      align-self: flex-start;
    }

    /* ===== HERO ===== */
    .hero {
      position: relative;
      overflow: hidden;
      padding: clamp(72px, 10vw, 140px) 0 clamp(60px, 8vw, 120px);
      background: var(--white);
    }

    .hero-bg {
      position: absolute;
      inset: 0;
      pointer-events: none;
      overflow: hidden;
    }

    .hero-blob {
      position: absolute;
      border-radius: 50%;
      filter: blur(80px);
      opacity: 0.25;
    }

    .hero-blob-1 {
      width: 700px;
      height: 700px;
      background: var(--purple);
      top: -200px;
      right: -200px;
    }

    .hero-blob-2 {
      width: 500px;
      height: 500px;
      background: var(--orange);
      bottom: -100px;
      left: -100px;
      opacity: 0.18;
    }

    .hero-blob-3 {
      width: 400px;
      height: 400px;
      background: #FF3CAC;
      top: 30%;
      left: 40%;
      opacity: 0.12;
    }

    .hero-content {
      position: relative;
      z-index: 1;
      max-width: 820px;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--purple-pale);
      color: var(--purple);
      border-radius: var(--radius-pill);
      padding: 7px 16px;
      font-size: 0.82rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      margin-bottom: 28px;
    }

    .hero-badge-dot {
      width: 7px;
      height: 7px;
      background: var(--purple);
      border-radius: 50%;
      animation: pulse 2s infinite;
    }

    @keyframes pulse {
      0%, 100% { opacity: 1; transform: scale(1); }
      50% { opacity: 0.5; transform: scale(0.8); }
    }

    .hero h1 {
      font-size: clamp(2.5rem, 6vw, 5rem);
      font-weight: 800;
      line-height: 1.08;
      letter-spacing: -0.03em;
      color: var(--black);
      margin-bottom: 28px;
    }

    .hero-gradient-text {
      background: linear-gradient(90deg, var(--purple) 0%, #FF3CAC 50%, var(--orange) 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero-sub {
      font-size: clamp(1rem, 2vw, 1.2rem);
      color: var(--gray-600);
      max-width: 560px;
      margin-bottom: 44px;
      line-height: 1.7;
    }

    .hero-actions {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
      align-items: center;
    }

    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 16px 36px;
      background: linear-gradient(135deg, var(--purple), #FF3CAC);
      color: var(--white);
      border-radius: var(--radius-pill);
      font-size: 1.05rem;
      font-weight: 700;
      transition: transform 0.2s, box-shadow 0.2s;
      box-shadow: 0 4px 20px rgba(118,56,250,0.35);
    }

    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 30px rgba(118,56,250,0.45);
    }

    .btn-primary:active { transform: translateY(0); }

    .hero-stats {
      margin-top: 64px;
      display: flex;
      gap: clamp(24px, 4vw, 56px);
      flex-wrap: wrap;
    }

    .hero-stat-value {
      font-size: clamp(1.8rem, 3.5vw, 2.8rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      background: linear-gradient(135deg, var(--purple), var(--orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      line-height: 1;
      margin-bottom: 4px;
    }

    .hero-stat-label {
      font-size: 0.88rem;
      color: var(--gray-400);
      font-weight: 500;
    }

    /* ===== SECTION SHARED ===== */
    .section { padding: clamp(64px, 8vw, 120px) 0; }

    .section-label {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--purple);
      margin-bottom: 16px;
    }

    .section-label::before {
      content: '';
      display: block;
      width: 20px;
      height: 2px;
      background: var(--purple);
      border-radius: 2px;
    }

    /* ===== FEATURES ===== */
    .section-features { background: var(--gray-50); }

    .features-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      align-items: center;
    }

    .features-text h2 {
      font-size: clamp(1.8rem, 3.5vw, 2.8rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.15;
      margin-bottom: 20px;
    }

    .features-text h2 a { color: var(--purple); }

    .features-text p {
      font-size: 1.05rem;
      color: var(--gray-600);
      line-height: 1.75;
      margin-bottom: 28px;
    }

    .features-link {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      color: var(--purple);
      font-weight: 700;
      font-size: 1rem;
      transition: gap 0.15s;
    }

    .features-link:hover { gap: 10px; }

    .features-visual {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
    }

    .feature-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 28px 22px;
      box-shadow: var(--shadow-card);
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-card-hover);
    }

    .feature-card:nth-child(2) { margin-top: 24px; }
    .feature-card:nth-child(4) { margin-top: -24px; }

    .feature-card-icon {
      width: 48px;
      height: 48px;
      border-radius: var(--radius-sm);
      margin-bottom: 14px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .feature-card-icon svg { width: 26px; height: 26px; }

    .feature-card-name {
      font-size: 1rem;
      font-weight: 700;
      color: var(--black);
      margin-bottom: 6px;
    }

    .feature-card-desc {
      font-size: 0.85rem;
      color: var(--gray-400);
      line-height: 1.5;
    }

    /* ===== SAFETY ===== */
    .section-safety { background: var(--white); }

    .safety-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      align-items: center;
    }

    .safety-visual {
      background: linear-gradient(135deg, #EEF7FF 0%, #E8F4FD 100%);
      border-radius: var(--radius-xl);
      padding: 48px 40px;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .safety-item {
      display: flex;
      align-items: flex-start;
      gap: 16px;
      background: var(--white);
      border-radius: var(--radius-md);
      padding: 18px 20px;
      box-shadow: 0 2px 12px rgba(0,0,0,0.06);
    }

    .safety-item-icon {
      width: 40px;
      height: 40px;
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .safety-item-icon svg { width: 20px; height: 20px; }

    .safety-item-text strong {
      display: block;
      font-size: 0.9rem;
      font-weight: 700;
      color: var(--black);
      margin-bottom: 3px;
    }

    .safety-item-text span {
      font-size: 0.82rem;
      color: var(--gray-400);
    }

    .safety-text h2 {
      font-size: clamp(1.8rem, 3.5vw, 2.8rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.15;
      margin-bottom: 20px;
    }

    .safety-text h2 a { color: var(--purple); }

    .safety-text p {
      font-size: 1.05rem;
      color: var(--gray-600);
      line-height: 1.75;
      margin-bottom: 28px;
    }

    /* ===== CREATORS ===== */
    .section-creators {
      background: var(--black);
      color: var(--white);
      position: relative;
      overflow: hidden;
    }

    .creators-bg {
      position: absolute;
      inset: 0;
      pointer-events: none;
    }

    .creators-blob {
      position: absolute;
      border-radius: 50%;
      filter: blur(100px);
      opacity: 0.3;
    }

    .creators-blob-1 {
      width: 600px;
      height: 600px;
      background: var(--purple);
      top: -200px;
      right: -100px;
    }

    .creators-blob-2 {
      width: 400px;
      height: 400px;
      background: var(--orange);
      bottom: -100px;
      left: 20%;
      opacity: 0.2;
    }

    .creators-content { position: relative; z-index: 1; }

    .creators-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      align-items: center;
    }

    .creators-text h2 {
      font-size: clamp(1.8rem, 3.5vw, 2.8rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.15;
      margin-bottom: 20px;
      color: var(--white);
    }

    .creators-text h2 a {
      background: linear-gradient(90deg, var(--orange-light), #FF3CAC);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .creators-text p {
      font-size: 1.05rem;
      color: rgba(255,255,255,0.65);
      line-height: 1.75;
      margin-bottom: 28px;
    }

    .creators-link {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      color: var(--orange-light);
      font-weight: 700;
      font-size: 1rem;
      transition: gap 0.15s;
    }

    .creators-link:hover { gap: 10px; }

    .creators-label { color: rgba(255,255,255,0.5); }
    .creators-label::before { background: var(--orange); }

    .creators-visual {
      display: grid;
      grid-template-columns: 1fr;
      gap: 16px;
    }

    .creator-stat-card {
      background: rgba(255,255,255,0.07);
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: var(--radius-lg);
      padding: 28px 32px;
      display: flex;
      align-items: center;
      gap: 24px;
      backdrop-filter: blur(8px);
      transition: background 0.2s, transform 0.2s;
    }

    .creator-stat-card:hover {
      background: rgba(255,255,255,0.12);
      transform: translateX(4px);
    }

    .creator-stat-icon {
      width: 56px;
      height: 56px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .creator-stat-icon svg { width: 28px; height: 28px; }

    .creator-stat-value {
      font-size: 2rem;
      font-weight: 800;
      letter-spacing: -0.03em;
      color: var(--white);
      line-height: 1;
      margin-bottom: 4px;
    }

    .creator-stat-label {
      font-size: 0.88rem;
      color: rgba(255,255,255,0.5);
    }

    /* ===== TAGLINE BANNER ===== */
    .tagline-banner {
      background: linear-gradient(135deg, var(--purple) 0%, #FF3CAC 50%, var(--orange) 100%);
      padding: clamp(48px, 6vw, 80px) var(--px);
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .tagline-banner::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.05'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    }

    .tagline-banner p {
      position: relative;
      font-size: clamp(1.6rem, 4vw, 3rem);
      font-weight: 800;
      color: var(--white);
      letter-spacing: -0.02em;
      line-height: 1.2;
    }

    /* ===== NEWS ===== */
    .section-news { background: var(--gray-50); }

    .news-header {
      display: flex;
      justify-content: space-between;
      align-items: flex-end;
      margin-bottom: 36px;
      gap: 20px;
      flex-wrap: wrap;
    }

    .news-header h2 {
      font-size: clamp(1.8rem, 3vw, 2.4rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      color: var(--black);
    }

    .view-more-link {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      color: var(--purple);
      font-weight: 700;
      font-size: 0.95rem;
      white-space: nowrap;
      transition: gap 0.15s;
      flex-shrink: 0;
    }

    .view-more-link:hover { gap: 10px; }

    /* Carousel wrapper */
    .carousel-outer {
      position: relative;
    }

    .carousel-track-wrap {
      overflow-x: auto;
      overflow-y: visible;
      -webkit-overflow-scrolling: touch;
      scroll-behavior: smooth;
      scrollbar-width: none;
      padding-bottom: 8px;
    }

    .carousel-track-wrap::-webkit-scrollbar { display: none; }

    .carousel-track {
      display: flex;
      gap: 20px;
      width: max-content;
      padding: 8px 4px 12px;
    }

    .news-card {
      width: 300px;
      flex-shrink: 0;
      background: var(--white);
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-card);
      transition: transform 0.2s, box-shadow 0.2s;
      cursor: pointer;
    }

    .news-card:hover {
      transform: translateY(-6px);
      box-shadow: var(--shadow-card-hover);
    }

    .news-thumb {
      width: 100%;
      height: 180px;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .news-thumb-inner {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .news-thumb-icon {
      width: 56px;
      height: 56px;
      background: rgba(255,255,255,0.25);
      backdrop-filter: blur(4px);
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .news-thumb-icon svg { width: 28px; height: 28px; fill: white; }

    .news-card-body { padding: 20px; }

    .news-tags {
      display: flex;
      flex-wrap: wrap;
      gap: 6px;
      margin-bottom: 12px;
    }

    .news-tag {
      display: inline-block;
      padding: 3px 10px;
      border-radius: var(--radius-pill);
      font-size: 0.7rem;
      font-weight: 700;
      letter-spacing: 0.04em;
    }

    .tag-announcements { background: var(--purple-pale); color: var(--purple); }
    .tag-tips { background: #FFF4E6; color: var(--orange); }
    .tag-product { background: #E6FFF4; color: #00A86B; }
    .tag-safety { background: #E6F4FF; color: #007AFF; }

    .news-card-title {
      font-size: 0.95rem;
      font-weight: 700;
      color: var(--black);
      line-height: 1.45;
      margin-bottom: 12px;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .news-card-date {
      font-size: 0.8rem;
      color: var(--gray-400);
      font-weight: 500;
    }

    /* Carousel nav arrows */
    .carousel-nav {
      display: flex;
      justify-content: flex-end;
      gap: 10px;
      margin-top: 20px;
    }

    .carousel-btn {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      background: var(--white);
      border: 2px solid var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: background 0.15s, border-color 0.15s, transform 0.15s;
    }

    .carousel-btn:hover {
      background: var(--purple);
      border-color: var(--purple);
      transform: scale(1.05);
    }

    .carousel-btn:hover svg { fill: white; }
    .carousel-btn svg { width: 18px; height: 18px; fill: var(--gray-600); transition: fill 0.15s; }

    /* ===== CTA DOWNLOAD ===== */
    .section-cta { background: var(--white); }

    .cta-box {
      background: linear-gradient(135deg, var(--gray-800) 0%, #2A1A5E 100%);
      border-radius: var(--radius-xl);
      padding: clamp(48px, 6vw, 80px) clamp(32px, 5vw, 80px);
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .cta-box::before {
      content: '';
      position: absolute;
      width: 400px;
      height: 400px;
      background: var(--purple);
      border-radius: 50%;
      top: -200px;
      right: -100px;
      filter: blur(80px);
      opacity: 0.4;
    }

    .cta-box::after {
      content: '';
      position: absolute;
      width: 300px;
      height: 300px;
      background: var(--orange);
      border-radius: 50%;
      bottom: -150px;
      left: 10%;
      filter: blur(80px);
      opacity: 0.25;
    }

    .cta-content { position: relative; z-index: 1; }

    .cta-box h2 {
      font-size: clamp(2rem, 4vw, 3.2rem);
      font-weight: 800;
      color: var(--white);
      letter-spacing: -0.03em;
      line-height: 1.1;
      margin-bottom: 8px;
    }

    .cta-box .cta-sub {
      font-size: clamp(1.4rem, 2.5vw, 2.2rem);
      font-weight: 800;
      background: linear-gradient(90deg, var(--purple-light), #FF3CAC, var(--orange-light));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      letter-spacing: -0.03em;
      margin-bottom: 36px;
    }

    .cta-buttons {
      display: flex;
      gap: 16px;
      justify-content: center;
      flex-wrap: wrap;
    }

    .store-btn {
      display: inline-flex;
      align-items: center;
      gap: 12px;
      padding: 14px 28px;
      background: rgba(255,255,255,0.1);
      border: 2px solid rgba(255,255,255,0.25);
      border-radius: var(--radius-md);
      color: var(--white);
      font-size: 0.95rem;
      font-weight: 700;
      transition: background 0.2s, border-color 0.2s, transform 0.2s;
      backdrop-filter: blur(4px);
    }

    .store-btn:hover {
      background: rgba(255,255,255,0.18);
      border-color: rgba(255,255,255,0.5);
      transform: translateY(-2px);
    }

    .store-btn svg { width: 28px; height: 28px; fill: white; }

    .store-btn-text { text-align: left; }
    .store-btn-text small { display: block; font-size: 0.7rem; font-weight: 500; opacity: 0.7; }
    .store-btn-text strong { display: block; font-size: 1rem; }

    /* ===== FOOTER ===== */
    .footer {
      background: var(--black);
      color: rgba(255,255,255,0.7);
      padding: clamp(48px, 6vw, 80px) 0 0;
    }

    .footer-logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      font-size: 1.25rem;
      color: var(--white);
      margin-bottom: 40px;
    }

    .footer-logo-icon {
      width: 36px;
      height: 36px;
      background: linear-gradient(135deg, var(--purple), var(--orange));
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .footer-logo-icon svg { width: 20px; height: 20px; fill: white; }

    .footer-nav-grid {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 32px 24px;
      margin-bottom: 48px;
    }

    .footer-col h4 {
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--white);
      margin-bottom: 16px;
    }

    .footer-col ul { list-style: none; }

    .footer-col ul li {
      margin-bottom: 10px;
    }

    .footer-col ul li a {
      font-size: 0.88rem;
      color: rgba(255,255,255,0.55);
      transition: color 0.15s;
      line-height: 1.5;
    }

    .footer-col ul li a:hover { color: var(--white); }

    .footer-col ul li a .ext {
      opacity: 0.5;
      font-size: 0.8em;
      margin-left: 2px;
    }

    .footer-divider {
      height: 1px;
      background: rgba(255,255,255,0.1);
      margin-bottom: 24px;
    }

    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-bottom: 32px;
      gap: 20px;
      flex-wrap: wrap;
    }

    .footer-bottom-left {
      display: flex;
      align-items: center;
      gap: 16px;
      flex-wrap: wrap;
    }

    .lang-selector {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 0.82rem;
      color: rgba(255,255,255,0.5);
      background: rgba(255,255,255,0.07);
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: var(--radius-pill);
      padding: 6px 14px;
      cursor: pointer;
      transition: background 0.15s;
    }

    .lang-selector:hover { background: rgba(255,255,255,0.12); }
    .lang-selector svg { width: 14px; height: 14px; fill: rgba(255,255,255,0.5); }

    .footer-legal {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }

    .footer-legal a {
      font-size: 0.78rem;
      color: rgba(255,255,255,0.35);
      transition: color 0.15s;
    }

    .footer-legal a:hover { color: rgba(255,255,255,0.7); }

    .footer-social {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .social-btn {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: rgba(255,255,255,0.08);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background 0.15s, transform 0.15s;
    }

    .social-btn:hover {
      background: rgba(255,255,255,0.18);
      transform: translateY(-2px);
    }

    .social-btn svg { width: 16px; height: 16px; fill: rgba(255,255,255,0.7); }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 900px) {
      .features-grid,
      .safety-grid,
      .creators-grid { grid-template-columns: 1fr; }

      .footer-nav-grid { grid-template-columns: repeat(3, 1fr); }

      .features-visual { order: -1; }
    }

    @media (max-width: 768px) {
      .hamburger { display: flex; }
      .btn-login { display: none; }
      .features-visual { grid-template-columns: 1fr 1fr; }
      .feature-card:nth-child(2) { margin-top: 0; }
      .feature-card:nth-child(4) { margin-top: 0; }
    }

    @media (max-width: 580px) {
      .footer-nav-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-bottom { flex-direction: column; align-items: flex-start; }
      .news-card { width: 270px; }
    }

    @media (max-width: 420px) {
      .hero-stats { gap: 20px; }
      .cta-buttons { flex-direction: column; align-items: center; }
      .footer-nav-grid { grid-template-columns: 1fr 1fr; }
    }
  </style>
</head>
<body>

  <!-- ===== HEADER ===== -->
  <header class="header" role="banner">
    <div class="container">
      <div class="header-inner">
        <a href="#" class="logo" aria-label="SnapFrame home">
          <div class="logo-icon" aria-hidden="true">
            <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 14H9V8h2v8zm4 0h-2V8h2v8z" opacity="0"/><rect x="3" y="3" width="8" height="8" rx="2"/><rect x="13" y="3" width="8" height="8" rx="2"/><rect x="3" y="13" width="8" height="8" rx="2"/><circle cx="17" cy="17" r="4"/></svg>
          </div>
          SnapFrame
        </a>

        <div class="header-actions">
          <a href="#" class="btn-login" role="button">Log in</a>
          <button
            class="hamburger"
            aria-label="Open navigation menu"
            aria-expanded="false"
            aria-controls="mobile-nav"
            id="hamburger-btn"
          >
            <span></span>
            <span></span>
            <span></span>
          </button>
        </div>
      </div>
    </div>
  </header>

  <!-- Mobile Nav Overlay -->
  <nav class="mobile-nav" id="mobile-nav" aria-label="Mobile navigation" role="navigation">
    <a href="#features">Features</a>
    <a href="#safety">Safety</a>
    <a href="#creators">Creators</a>
    <a href="#news">News</a>
    <a href="#" class="mobile-nav-login" role="button">Log in</a>
  </nav>

  <main id="main-content">

    <!-- ===== HERO ===== -->
    <section class="hero" aria-labelledby="hero-heading">
      <div class="hero-bg" aria-hidden="true">
        <div class="hero-blob hero-blob-1"></div>
        <div class="hero-blob hero-blob-2"></div>
        <div class="hero-blob hero-blob-3"></div>
      </div>
      <div class="container">
        <div class="hero-content">
          <div class="hero-badge" aria-hidden="true">
            <span class="hero-badge-dot"></span>
            Now live worldwide
          </div>
          <h1 id="hero-heading">
            SnapFrame brings you closer to the <span class="hero-gradient-text">people and things you love</span>
          </h1>
          <p class="hero-sub">
            SnapFrame is a social media platform that makes it easy to capture, create, and share what you love with the people who matter most.
          </p>
          <div class="hero-actions">
            <a href="#" class="btn-primary" role="button">
              Try it now
              <svg viewBox="0 0 24 24" fill="white" width="18" height="18" aria-hidden="true"><path d="M13 5l7 7-7 7M5 12h15" stroke="white" stroke-width="2" stroke-linecap="round" fill="none"/></svg>
            </a>
          </div>
          <div class="hero-stats" role="list" aria-label="Platform statistics">
            <div role="listitem">
              <div class="hero-stat-value">2B+</div>
              <div class="hero-stat-label">Monthly active users</div>
            </div>
            <div role="listitem">
              <div class="hero-stat-value">150+</div>
              <div class="hero-stat-label">Countries available</div>
            </div>
            <div role="listitem">
              <div class="hero-stat-value">100M+</div>
              <div class="hero-stat-label">Creators worldwide</div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- ===== FEATURES ===== -->
    <section class="section section-features" id="features" aria-labelledby="features-heading">
      <div class="container">
        <div class="features-grid">
          <div class="features-text">
            <div class="section-label" aria-hidden="true">Features</div>
            <h2 id="features-heading">
              Share what you're into with the people who get you with all our <a href="#">features →</a>
            </h2>
            <p>SnapFrame's suite of creative tools — from short-form video to disappearing stories and direct messaging — lets you express yourself and connect with the communities that matter most. Explore Clips, Stories, DMs, and Search &amp; Explore to find your people.</p>
            <a href="#" class="features-link" aria-label="Explore all features">
              features →
            </a>
          </div>

          <div class="features-visual" aria-hidden="true">
            <div class="feature-card">
              <div class="feature-card-icon" style="background: #F3EEFF;">
                <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
                  <path d="M15 10l4.553-2.276A1 1 0 0121 8.723v6.554a1 1 0 01-1.447.894L15 14v-4z" fill="#7638FA"/>
                  <rect x="3" y="6" width="12" height="12" rx="2" fill="#7638FA" opacity=".3"/>
                </svg>
              </div>
              <div class="feature-card-name">Clips</div>
              <div class="feature-card-desc">Short-form video magic, straight to your feed</div>
            </div>
            <div class="feature-card">
              <div class="feature-card-icon" style="background: #FFF4E6;">
                <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
                  <circle cx="12" cy="12" r="9" fill="#FF7A00" opacity=".3"/>
                  <path d="M12 7v5l3 3" stroke="#FF7A00" stroke-width="2" stroke-linecap="round"/>
                </svg>
              </div>
              <div class="feature-card-name">Stories</div>
              <div class="feature-card-desc">Moments that disappear, memories that don't</div>
            </div>
            <div class="feature-card">
              <div class="feature-card-icon" style="background: #E6FFF4;">
                <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
                  <path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2v10z" fill="#00A86B" opacity=".3"/>
                  <path d="M8 10h8M8 13h5" stroke="#00A86B" stroke-width="1.5" stroke-linecap="round"/>
                </svg>
              </div>
              <div class="feature-card-name">DMs</div>
              <div class="feature-card-desc">Real conversations with the people you care about</div>
            </div>
            <div class="feature-card">
              <div class="feature-card-icon" style="background: #E6F4FF;">
                <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
                  <circle cx="11" cy="11" r="7" fill="#007AFF" opacity=".3"/>
                  <path d="M16.5 16.5L21 21" stroke="#007AFF" stroke-width="2" stroke-linecap="round"/>
                </svg>
              </div>
              <div class="feature-card-name">Search &amp; Explore</div>
              <div class="feature-card-desc">Discover new communities built for you</div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- ===== SAFETY ===== -->
    <section class="section section-safety" id="safety" aria-labelledby="safety-heading">
      <div class="container">
        <div class="safety-grid">
          <div class="safety-visual" aria-hidden="true">
            <div class="safety-item">
              <div class="safety-item-icon" style="background: #E6F4FF;">
                <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M12 2L4 6v6c0 5.55 3.84 10.74 8 12 4.16-1.26 8-6.45 8-12V6l-8-4z" fill="#007AFF" opacity=".3"/>
                  <path d="M9 12l2 2 4-4" stroke="#007AFF" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                </svg>
              </div>
              <div class="safety-item-text">
                <strong>Privacy Controls</strong>
                <span>Manage who sees your content</span>
              </div>
            </div>
            <div class="safety-item">
              <div class="safety-item-icon" style="background: #F3EEFF;">
                <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <rect x="3" y="11" width="18" height="11" rx="2" fill="#7638FA" opacity=".3"/>
                  <path d="M7 11V7a5 5 0 0110 0v4" stroke="#7638FA" stroke-width="2" stroke-linecap="round"/>
                </svg>
              </div>
              <div class="safety-item-text">
                <strong>Account Security</strong>
                <span>Two-factor authentication &amp; alerts</span>
              </div>
            </div>
            <div class="safety-item">
              <div class="safety-item-icon" style="background: #FFF4E6;">
                <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" fill="#FF7A00" opacity=".3"/>
                  <path d="M9 9l6 6M15 9l-6 6" stroke="#FF7A00" stroke-width="2" stroke-linecap="round"/>
                </svg>
              </div>
              <div class="safety-item-text">
                <strong>Content Filters</strong>
                <span>Block sensitive content automatically</span>
              </div>
            </div>
            <div class="safety-item">
              <div class="safety-item-icon" style="background: #E6FFF4;">
                <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <circle cx="12" cy="12" r="9" fill="#00A86B" opacity=".3"/>
                  <path d="M12 8v4l2 2" stroke="#00A86B" stroke-width="2" stroke-linecap="round"/>
                </svg>
              </div>
