  <script>
    // Hamburger menu toggle
    const hamburgerBtn = document.getElementById('hamburger-btn');
    const mobileNav = document.getElementById('mobile-nav');

    hamburgerBtn.addEventListener('click', () => {
      const isOpen = hamburgerBtn.getAttribute('aria-expanded') === 'true';
      hamburgerBtn.setAttribute('aria-expanded', String(!isOpen));
      hamburgerBtn.setAttribute('aria-label', isOpen ? 'Open navigation menu' : 'Close navigation menu');
      mobileNav.classList.toggle('open', !isOpen);
      document.body.style.overflow = isOpen ? '' : 'hidden';
    });

    // Close mobile nav when a link is clicked
    mobileNav.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => {
        hamburgerBtn.setAttribute('aria-expanded', 'false');
        hamburgerBtn.setAttribute('aria-label', 'Open navigation menu');
        mobileNav.classList.remove('open');
        document.body.style.overflow = '';
      });
    });

    // Close mobile nav on Escape key
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape' && mobileNav.classList.contains('open')) {
        hamburgerBtn.setAttribute('aria-expanded', 'false');
        mobileNav.classList.remove('open');
        document.body.style.overflow = '';
        hamburgerBtn.focus();
      }
    });

    // News Carousel
    const trackWrap = document.getElementById('carousel-track-wrap');
    const prevBtn = document.getElementById('carousel-prev');
    const nextBtn = document.getElementById('carousel-next');
    const SCROLL_AMOUNT = 320;

    nextBtn.addEventListener('click', () => {
      trackWrap.scrollBy({ left: SCROLL_AMOUNT, behavior: 'smooth' });
    });

    prevBtn.addEventListener('click', () => {
      trackWrap.scrollBy({ left: -SCROLL_AMOUNT, behavior: 'smooth' });
    });

    // Update button states based on scroll position
    function updateCarouselBtns() {
      prevBtn.style.opacity = trackWrap.scrollLeft <= 0 ? '0.4' : '1';
      prevBtn.disabled = trackWrap.scrollLeft <= 0;
      const maxScroll = trackWrap.scrollWidth - trackWrap.clientWidth;
      nextBtn.style.opacity = trackWrap.scrollLeft >= maxScroll - 1 ? '0.4' : '1';
      nextBtn.disabled = trackWrap.scrollLeft >= maxScroll - 1;
    }

    trackWrap.addEventListener('scroll', updateCarouselBtns, { passive: true });
    updateCarouselBtns();

    // Touch/swipe support for carousel (pointer events)
    let isDragging = false;
    let startX = 0;
    let scrollStart = 0;

    trackWrap.addEventListener('pointerdown', e => {
      if (e.pointerType === 'mouse') {
        isDragging = true;
        startX = e.clientX;
        scrollStart = trackWrap.scrollLeft;
        trackWrap.style.cursor = 'grabbing';
        trackWrap.setPointerCapture(e.pointerId);
      }
    });

    trackWrap.addEventListener('pointermove', e => {
      if (!isDragging) return;
      const dx = e.clientX - startX;
      trackWrap.scrollLeft = scrollStart - dx;
    });

    trackWrap.addEventListener('pointerup', () => {
      isDragging = false;
      trackWrap.style.cursor = '';
    });

